  "settings.httpProxy": "HTTP-прокси",
  "settings.httpProxyDescription":
    "Направлять исходящий трафик моделей, MCP, инструментов команд и рендерера приложения через этот прокси; системные переменные среды не считываются. Если оставить поле пустым, этот трафик пойдёт напрямую, а встроенный браузер будет следовать системным настройкам прокси. Перезапустите приложение, чтобы изменения вступили в силу.",
