  "settings.modelProvider.fieldHelp": "О поле {field}",
  "settings.modelProvider.help.contextWindow":
    "Объём контекста, который модель может обработать за раз, в токенах. DeepVibe использует его для управления контекстом.\nНе превышайте фактический лимит модели.",
  "settings.modelProvider.help.maxOutputTokens":
    "Максимальное число токенов, которое может сгенерировать один запрос к модели.\nНе превышайте фактический лимит модели.",
  "settings.modelProvider.help.inputModalities":
    "Задайте типы контента, которые может принимать модель:\n\n- **Текст**: принимает текстовый контент. Обязательно.\n- **Изображения**: принимает изображения.\n- **Видео**: принимает видео.\n- **PDF**: принимает документы PDF напрямую.",
  "settings.modelProvider.help.outputModalities":
    "Тип контента ответов модели. Сейчас поддерживается только текст.",
  "settings.modelProvider.help.capabilities":
    "- **Структурированный вывод**: поддерживает ограничения JSON Schema для полей, типов и структуры вывода.\n- **Встроенный веб-поиск**: поддерживает встроенную в API модели функцию веб-поиска.\n- **Системные сообщения в середине диалога**: поддерживает вставку системных инструкций во время диалога.\n\nНе включайте возможности, которые модель не поддерживает.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Задайте уровни рассуждения, доступные в чате. **Они должны идти от наименьших усилий рассуждения к наибольшим**.\nНе настраивайте уровни рассуждения, которые модель не поддерживает.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "Используйте выражение CEL, чтобы сопоставить текущий уровень рассуждения `reasoningLevel` с полями запроса к API модели. Объект JSON, возвращаемый выражением, объединяется с телом исходящего запроса.",
  "settings.modelProvider.help.advanced":
    "**Схема инструментов MFJS**: включает совместимость с Moonshot Flavored JSON Schema, которую обычно использует API модели Kimi от Moonshot. Включайте, только если API модели требует этот формат.",
  "settings.modelProvider.help.followRecommendedConfig":
    "Подбирает рекомендуемые параметры по ID модели, базовому URL и формату API. DeepVibe постоянно обновляет рекомендации и автоматически синхронизирует их с вами.\nЕсли вы измените настройку вручную, она переходит на ручное управление и перестаёт следовать обновлениям рекомендаций; остальные настройки продолжат управляться умной настройкой.",
